interface Events { price: { prev: number; next: number } }
class PriceTicker extends EventTarget {
  private price = 0;
  on<K extends keyof Events>(type: K, fn: (e: CustomEvent<Events[K]>) => void): () => void {
    const h = fn as EventListener;
    this.addEventListener(type, h);
    return () => this.removeEventListener(type, h);   // removal handle
  }
  setPrice(next: number) {
    const prev = this.price; this.price = next;
    this.dispatchEvent(new CustomEvent<Events["price"]>("price", { detail: { prev, next } })); }
}

